def fibonacci_sequence(n):
    if n <= 0:
        with open("empty_sequence.txt", "w") as f_empty:
            f_empty.write("No Fibonacci numbers requested.")
        return []
    elif n == 1:
        with open("first_number.txt", "w") as f_one:
            f_one.write("0")
        return [0]
    else:
        sequence = [0, 1]
        for i in range(2, n):
            next_fib = sequence[i-1] + sequence[i-2]
            sequence.append(next_fib)
        with open("fibonacci_output.txt", "w") as f_out:
            for num in sequence:
                f_out.write(str(num) + "\n")

        with open("fibonacci_summary.txt", "w") as f_summary:
            f_summary.write(f"Generated {n} Fibonacci numbers.")

        return sequence

