def calculate_grade(score):
    with open('grades.txt', 'a') as f:
        f.write(f"Score received: {score}\n")

    if 90 <= score <= 100:
        grade = 'A'
    elif 80 <= score < 90:
        grade = 'B'
    elif 70 <= score < 80:
        grade = 'C'
    elif 60 <= score < 70:
        grade = 'D'
    else:
        grade = 'F'

    with open('grade_output.txt', 'w') as f:
        f.write(f"The grade for score {score} is: {grade}\n")

    with open('grade_summary.txt', 'a') as f:
        f.write(f"{score},{grade}\n")

    with open('latest_grade.txt', 'w') as f:
        f.write(f"Last processed score: {score}, Grade: {grade}\n")

    return grade

