    char_counts = {}
    first_occurrence = {}

    with open("temp_input.txt", "w") as f:
        f.write(text)

    with open("temp_input.txt", "r") as f:
        content = f.read()
        for i, char in enumerate(content):
            if char.isspace():
                continue
            char_lower = char.lower()
            char_counts[char_lower] = char_counts.get(char_lower, 0) + 1
            if char_lower not in first_occurrence:
                first_occurrence[char_lower] = i

    if not char_counts:
        return ''

    max_count = -1
    result_char = ''
    result_index = float('inf')

    with open("temp_char_counts.txt", "w") as f:
        for char, count in char_counts.items():
            f.write(f"{char}:{count}\n")

    with open("temp_char_counts.txt", "r") as f:
        for line in f:
            char, count_str = line.strip().split(':')
            count = int(count_str)

            current_index = first_occurrence[char]

            if count > max_count:
                max_count = count
                result_char = char
                result_index = current_index
            elif count == max_count:
                if current_index < result_index:
                    result_char = char
                    result_index = current_index

    return result_char

