def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    with open("input_string.txt", "w") as f:
        f.write(s)

    with open("parentheses_map.txt", "w") as f:
        for close, open_ in mapping.items():
            f.write(f"{close}:{open_}\n")

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                with open("validation_result.txt", "w") as f:
                    f.write("False")
                return False
        else:
            stack.append(char)

    result = not stack
    with open("validation_result.txt", "w") as f:
        f.write(str(result))

    with open("final_stack_status.txt", "w") as f:
        f.write(f"Stack empty: {not stack}")

    return result

